using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
internal static class SpriteMaskLifetimeTests {
 static int checks;static void Yes(bool v,string m){checks++;if(!v)throw new Exception(m);}
 static double N(Dictionary<string,object> d,string k){return Convert.ToDouble(d[k]);}
 static SpriteMeta Meta(){return new SpriteMeta{originX=10,originY=12,frames=1,colliders=new[]{new SpriteCollider{left=0,top=1,right=20,bottom=22}},revision="test"};}
 static Track Track(){return new Track{id="e",kind="emitter",start=0,end=0,count=1,interval=1,x=-5,y=304,scale=.5,speed=0,life=10,sprite="Mask",despawnBounds="sprite-mask"};}
 static BulletWorld World(Track t){return new BulletWorld(new EditorState{tracks=new List<Track>{t}},new RoomData{width=800,height=608},null,n=>Meta());}
 static void Main(string[] args){var json=new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue};var oracle=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(args[0]));int exact=0;double error=0;foreach(var obj in (System.Collections.ArrayList)oracle["cases"]){var c=(Dictionary<string,object>)obj;var m=(Dictionary<string,object>)c["meta"];var expected=(Dictionary<string,object>)c["bounds"];var meta=new SpriteMeta{originX=(int)N(m,"originX"),originY=(int)N(m,"originY"),colliders=new[]{new SpriteCollider{left=N(m,"left"),top=N(m,"top"),right=N(m,"right"),bottom=N(m,"bottom")}}};var b=SpriteMaskLifetime.Bounds(meta,0,N(c,"x"),N(c,"y"),N(c,"scaleX"),N(c,"scaleY"),N(c,"angle"));foreach(var k in new[]{"left","top","right","bottom"}){double v=(double)typeof(SpriteCollider).GetField(k).GetValue(b),e=N(expected,k);if(v==e)exact++;error=Math.Max(error,Math.Abs(v-e));}Yes(SpriteMaskLifetime.Outside(b,800,608,0)==(bool)c["outside"],"strict oracle predicate");}Console.WriteLine("oracle exact components="+exact+"/960 max error="+error.ToString("R"));
 var t=Track();var w=World(t);w.Seek(0);Yes(w.bullets.Count==1,"tangent retained birth");w.Seek(10);Yes(w.bullets.Count==0,"fixed earliest");w.Seek(0);Yes(w.bullets.Count==1,"reverse rebuilt");t=Track();t.x=-5.000001;w=World(t);w.Seek(0);Yes(w.bullets.Count==0,"outside birth");foreach(double speed in new[]{-2.0,0,2.0}){t=Track();t.x=-6;t.speed=speed;w=World(t);w.Seek(0);Yes(w.bullets.Count==0,"velocity independent");}t=Track();t.x=-6;t.speed=2;t.moveOnBirth=true;w=World(t);w.Seek(0);Yes(w.bullets.Count==1,"birth move before bounds");t=Track();t.x=-6;t.despawnBounds="none";w=World(t);w.Seek(0);Yes(w.bullets.Count==1,"legacy unchanged");t=Track();t.x=-5;t.deathEffect="shrink";t.deathFrames=10;w=World(t);w.Seek(1);Yes(w.bullets.Count==1&&w.bullets[0].deathStart==1&&!w.bullets[0].collision,"current shrink factor triggers transition");
 t=Track();t.x=-6;t.bulletActions.Add(new BulletAction{type="split",start=0,count=3});w=World(t);w.Seek(0);Yes(w.bullets.Count==0,"boundary suppresses queued split");
 t=Track();t.boundsSprite="Other";int called=0;w=new BulletWorld(new EditorState{tracks=new List<Track>{t}},null,null,n=>{Yes(n=="Other","independent mask identity");called++;return Meta();});w.Seek(0);Yes(called==1,"resolver called");
 var saved=json.Deserialize<Track>(json.Serialize(t));Yes(saved.boundsSprite=="Other"&&saved.despawnBounds=="sprite-mask","json roundtrip");Yes(t.Snapshot().boundsSprite=="Other","snapshot");
 var empty=new SpriteMeta{originX=20,originY=30,colliders=new[]{new SpriteCollider{empty=true}}};var eb=SpriteMaskLifetime.Bounds(empty,0,8,9,-2,0,72);Yes(eb.left==8&&eb.top==9,"empty origin fallback");
 var viewMeta=new SpriteMeta{colliders=new[]{new SpriteCollider{left=-10,top=-1,right=10,bottom=1}}};var vb=SpriteMaskLifetime.Bounds(viewMeta,0,0,0,1,1,45,BulletLifetime.Bounds(0,0,20,2,45));Yes(Math.Abs(vb.right-10)<1e-12&&Math.Abs(vb.bottom-1)<1e-12,"view four corner projection");Yes(!SpriteMaskLifetime.Outside(vb,20,2,0,true),"view equality");Yes(!SpriteMaskLifetime.Outside(new SpriteCollider{left=11,right=12,top=0,bottom=1},20,2,1,true),"world margin");
 var pm=new SpriteMeta{colliders=new[]{new SpriteCollider{left=0,right=2,top=0,bottom=2},new SpriteCollider{left=8,right=9,top=8,bottom=9}}};Yes(SpriteMaskLifetime.Bounds(pm,1,0,0,1,1,0).left==8,"perframe");Yes(SpriteMaskLifetime.Bounds(pm,-1,0,0,1,1,0).left==8,"negative frame normalization");
 bool threw=false;try{w=new BulletWorld(new EditorState{tracks=new List<Track>{Track()}});w.Seek(0);}catch(InvalidOperationException ex){threw=ex.Message.Contains("metadata");}Yes(threw,"actionable missing metadata");Console.WriteLine("SpriteMaskLifetimeTests passed "+checks);
 }
}
